/* AgroMatch frontend (vanilla JS, no build step). Served by FastAPI at /. */
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let T=localStorage.tok||'';
const S={scr:T?'boot':'onb',ob:0,auth:'register',tab:'home',ov:null,me:null,seg:'swipe',disc:[],known:{},matches:[],tracks:[],pri:[],pts:[],loc:null,rot:null,rotF:null,rotP:'',sc:{rain:0,temp:0,drought:0},rs:'current',cop:{mode:'ask',hist:[],out:{},busy:false,field:null},cam:null,layer:'sat',notif:0,notifN:0,thread:null,expl:false};
const LV={EXCELLENT:'#2f7a4a',GOOD:'#6a9f4c',MODERATE:'#c79a2b',POOR:'#c2682f',CRITICAL:'#a8322a'};
const TG={n:['NASA','n'],s:['SIMULATED','s_'],f:['FARMER-PROVIDED','f_'],a:['AI-GENERATED','a_']},tag=k=>`<span class="tag ${TG[k][1]}">${TG[k][0]}</span>`;
const CROPS=['wheat','barley','maize','oat','sorghum','sunflower','rapeseed','chickpea','lentil','pea','soybean','vetch','fallow'];
const ICN={home:'<path d="M3 11l9-8 9 8M5 10v10h14V10"/>',earth:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>',disc:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c.5-4 3-6 6.5-6s6 2 6.5 6M17 4.5a3.5 3.5 0 010 7M21.5 20c-.3-2.5-1.4-4.2-3.3-5"/>',rot:'<path d="M20 11a8 8 0 00-14-4L4 9M4 4v5h5M4 13a8 8 0 0014 4l2-2M20 20v-5h-5"/>',co:'<path d="M12 3l2 5 5 2-5 2-2 5-2-5-5-2 5-2z"/>',bell:'<path d="M6 16V11a6 6 0 0112 0v5l2 2H4zM10 21h4"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',x:'<path d="M6 6l12 12M18 6L6 18"/>',heart:'<path d="M12 20s-8-5-8-11a4.5 4.5 0 018-2.5A4.5 4.5 0 0120 9c0 6-8 11-8 11z"/>',back:'<path d="M15 5l-7 7 7 7"/>'};
const ic=n=>`<svg class="i" viewBox="0 0 24 24">${ICN[n]||featureIcons[n]||ICN.home}</svg>`;
async function api(p,o={}){const r=await fetch('/api'+p,{method:o.m||(o.b?'POST':'GET'),headers:{'Content-Type':'application/json',...(T?{Authorization:'Bearer '+T}:{})},body:o.b?JSON.stringify(o.b):undefined});const j=await r.json().catch(()=>({}));if(!r.ok){if(r.status==401&&T){T='';localStorage.tok='';S.scr='auth';draw()}throw new Error(typeof j.detail=='string'?j.detail:r.statusText)}return j}
function toast(m){document.querySelectorAll('.toast').forEach(e=>e.remove());$('#app').insertAdjacentHTML('beforeend',`<div class="toast">${esc(m)}</div>`);setTimeout(()=>document.querySelectorAll('.toast').forEach(e=>e.remove()),3200)}
const tryit=async(f)=>{try{return await f()}catch(e){toast(e.message)}};
const md=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').split('\n').map(l=>l.trim()?`<p>${l}</p>`:'').join('');
const when=t=>new Date(t*1000).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const lvpill=(l,s)=>l?`<span style="background:${LV[l]};color:#fff;border-radius:99px;padding:2px 9px;font-size:11px;font-weight:700">${l}${s!=null?' '+s:''}</span>`:'';
/* ---------- charts ---------- */
function line(a,lab,col='var(--pri)',w=300,h=70){const v=a.map(x=>x??0),mx=Math.max(...v),mn=Math.min(...v),p=v.map((y,i)=>[i*w/(v.length-1||1),h-6-(y-mn)/(mx-mn||1)*(h-14)]),d=p.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join('');return`<svg viewBox="0 0 ${w} ${h+14}" width="100%"><path d="${d}L${w} ${h}L0 ${h}Z" fill="${col}" opacity=".12"/><path d="${d}" fill="none" stroke="${col}" stroke-width="2.5"/>${lab.map((l,i)=>i%2?'':`<text x="${p[i][0]}" y="${h+12}" font-size="9" fill="var(--mut)" text-anchor="middle">${l}</text>`).join('')}</svg>`}
function bars(a,lab,col='#4a8fb5',w=300,h=70){const mx=Math.max(...a,1),bw=w/a.length;return`<svg viewBox="0 0 ${w} ${h+14}" width="100%">${a.map((v,i)=>`<rect x="${i*bw+3}" y="${h-v/mx*(h-6)}" width="${bw-6}" height="${v/mx*(h-6)}" rx="3" fill="${col}"/><text x="${i*bw+bw/2}" y="${h+12}" font-size="9" fill="var(--mut)" text-anchor="middle">${lab[i]}</text>`).join('')}</svg>`}
function dna(m){const mo=(m.monthly||[]).slice(-12);if(mo.length<6)return'';const R=a=>{const mx=Math.max(...a.map(v=>v||0))||1;return a.map(v=>(v||0)/mx)},poly=(a,c,o)=>`<polygon points="${a.map((v,i)=>{const g=i/a.length*2*Math.PI-Math.PI/2,r=18+v*40;return(60+r*Math.cos(g)).toFixed(1)+','+(60+r*Math.sin(g)).toFixed(1)}).join(' ')}" fill="${c}" fill-opacity="${o}" stroke="${c}" stroke-width="1.5"/>`;return`<svg viewBox="0 0 120 120" width="120">${poly(R(mo.map(x=>x.rain)),'#4a8fb5',.25)}${poly(R(mo.map(x=>x.temp)),'#c79a2b',.2)}${poly(R(mo.map(x=>x.wet)),'var(--pri)',.35)}</svg>`}
function art(t){const c=LV[t.level]||'#1F4D36',r=(t.id*7919)%97;return`<svg viewBox="0 0 200 200" width="100%" style="border-radius:18px"><defs><linearGradient id="ag" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="#10261b"/></linearGradient></defs><rect width="200" height="200" fill="url(#ag)"/>${[0,1,2,3,4,5].map(i=>`<circle cx="${60+(r*i)%90}" cy="${70+(r*3+i*23)%80}" r="${14+i*14}" fill="none" stroke="#fff" stroke-opacity="${.5-i*.07}" stroke-width="${t.level=='CRITICAL'?.8:2}" ${t.level=='CRITICAL'||t.level=='POOR'?'stroke-dasharray="4 6"':''}/>`).join('')}</svg>`}
/* ---------- maps ---------- */
const maps={};
function mkMap(id,o={}){if(maps[id])maps[id].remove();if(!window.maplibregl){const el=document.getElementById(id);if(el)el.innerHTML='<div class="warn">Interactive maps require an internet connection to load MapLibre. You can still browse other AgroMatch sections.</div>';const empty={remove(){},on(){},getCanvas(){return {style:{}}},flyTo(){},addControl(){},getCenter(){return {toArray:()=>[0,0]}},getZoom(){return 1},getPitch(){return 0}};maps[id]=empty;return empty}const m=new maplibregl.Map({container:id,center:o.center||[0,20],zoom:o.zoom??1.6,pitch:o.pitch||0,maxPitch:80,style:{version:8,projection:{type:'globe'},sources:{sat:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,maxzoom:18,attribution:'Imagery © Esri'},dem:{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],encoding:'terrarium',tileSize:256,maxzoom:14,attribution:'Terrain: Mapzen/AWS'}},layers:[{id:'bg',type:'background',paint:{'background-color':'#0b1d2a'}},{id:'sat',type:'raster',source:'sat'}]}});m.addControl(new maplibregl.NavigationControl({visualizePitch:true}));m.on('load',()=>{m.setTerrain({source:'dem',exaggeration:1.3});o.onload&&o.onload(m)});maps[id]=m;return m}
const fc=f=>({type:'FeatureCollection',features:f});
const polyF=(f)=>({type:'Feature',properties:{id:f.id,name:f.name},geometry:{type:'Polygon',coordinates:[[...f.polygon,f.polygon[0]]]}});
function addFields(m,fields,sel){m.addSource('flds',{type:'geojson',data:fc(fields.map(polyF))});m.addLayer({id:'ffill',type:'fill',source:'flds',paint:{'fill-color':'#7CFC9A','fill-opacity':.25}});m.addLayer({id:'fline',type:'line',source:'flds',paint:{'line-color':'#fff','line-width':2.5}});if(sel)m.on('click','ffill',e=>sel(e.features[0].properties.id,e.lngLat));}
function fit(m,pts){const b=new maplibregl.LngLatBounds(pts[0],pts[0]);pts.forEach(p=>b.extend(p));m.fitBounds(b,{padding:40,duration:0,maxZoom:17})}
async function geocode(q){const m=String(q||'').trim().match(/^(-?\d+(?:\.\d+)?)\s*[,;]\s*(-?\d+(?:\.\d+)?)$/);if(m){const lat=Number(m[1]),lon=Number(m[2]);if(lat>=-90&&lat<=90&&lon>=-180&&lon<=180)return {lat,lon,name:'Coordinates'};throw new Error('Coordinates must be latitude, longitude in valid ranges')}const r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q));const j=await r.json();if(!j.length)throw new Error('Place not found');return{lat:+j[0].lat,lon:+j[0].lon,name:j[0].display_name}}
const LAY={sat:{n:'Satellite',src:'Esri World Imagery (not NASA)',res:'≈0.3–10 m, varies',unit:'RGB',freq:'Mosaic, mixed dates',lim:'Acquisition date varies by location; not a time series.'},
ndvi:{n:'Vegetation',id:'MODIS_Terra_NDVI_8Day',lvl:9,ext:'png',src:'NASA MODIS Terra NDVI via GIBS',res:'250 m',unit:'NDVI (unitless, −1…1)',freq:'8-day composite',lim:'Clouds cause gaps; 250 m pixels blend small fields.'},
rain:{n:'Rainfall',id:'IMERG_Precipitation_Rate',lvl:6,ext:'png',src:'NASA GPM IMERG via GIBS',res:'≈10 km (0.1°)',unit:'mm/hr',freq:'30 minutes',lim:'Too coarse for single-field rainfall.'},
temp:{n:'Temperature',id:'MODIS_Terra_Land_Surface_Temp_Day',lvl:7,ext:'png',src:'NASA MODIS Terra land surface temperature via GIBS',res:'1 km',unit:'K (surface, not air temp)',freq:'Daily, clear-sky only',lim:'Cloud gaps. ECOSTRESS (~70 m) needs NASA AppEEARS access—not enabled in this build.'},
sm:{n:'Soil moisture',id:'SMAP_L4_Analyzed_Root_Zone_Soil_Moisture',lvl:6,ext:'png',src:'NASA SMAP L4 via GIBS',res:'≈9 km',unit:'m³/m³',freq:'3-hourly (model + SMAP)',lim:'Regional estimate only. Verify layer ID in GIBS GetCapabilities.'}};
function setLayer(k,date){const m=maps.earth;if(!m||!window.maplibregl)return;S.layer=k;if(m.getLayer('gibs'))m.removeLayer('gibs');if(m.getSource('gibs'))m.removeSource('gibs');const L=LAY[k];if(L.id){m.addSource('gibs',{type:'raster',tiles:[`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/${L.id}/default/${date}/GoogleMapsCompatible_Level${L.lvl}/{z}/{y}/{x}.${L.ext}`],tileSize:256,maxzoom:L.lvl,attribution:'NASA GIBS'});m.addLayer({id:'gibs',type:'raster',source:'gibs',paint:{'raster-opacity':.75}},m.getLayer('ffill')?'ffill':undefined)}
 document.querySelectorAll('#lays .chip').forEach(c=>c.classList.toggle('on',c.dataset.k==k));$('#einfo').innerHTML=`<b>${L.n}</b> ${L.id?tag('n'):''}<div class="mut">Source: ${L.src}<br>Date: ${L.id?date:'n/a'} · Resolution: ${L.res} · Units: ${L.unit} · Frequency: ${L.freq}</div><div class="warn">${L.lim} Missing tiles = no observation for that date.</div>`}
/* ---------- audio player ---------- */
const P={a:new Audio(),ctx:null,an:null};P.a.crossOrigin='anonymous';
function play(t){S.cur=t;P.a.src=t.url;P.ctx&&P.ctx.resume();P.a.play().catch(()=>{});$('#player').style.display='block';$('#pt').textContent=t.title+' · '+t.level;if(!P.ctx){P.ctx=new AudioContext();const s=P.ctx.createMediaElementSource(P.a);P.an=P.ctx.createAnalyser();P.an.fftSize=64;s.connect(P.an);P.an.connect(P.ctx.destination);viz()}}
function viz(){const c=$('#pc'),g=c.getContext('2d');c.width=c.clientWidth*2;c.height=52;const d=new Uint8Array(P.an.frequencyBinCount);(function f(){requestAnimationFrame(f);P.an.getByteFrequencyData(d);g.clearRect(0,0,c.width,c.height);const w=c.width/d.length;d.forEach((v,i)=>{g.fillStyle='rgba(255,255,255,.85)';const h=v/255*c.height;g.fillRect(i*w+2,c.height-h,w-4,h)})})()}
P.a.ontimeupdate=()=>$('#ps').value=P.a.duration?P.a.currentTime/P.a.duration*1000:0;P.a.onplay=()=>$('#pp').textContent='❚❚';P.a.onpause=()=>$('#pp').textContent='▶';
$('#ps').oninput=e=>{if(P.a.duration)P.a.currentTime=e.target.value/1000*P.a.duration};$('#pv').oninput=e=>P.a.volume=e.target.value/100;$('#pp').onclick=()=>P.a.paused?P.a.play():P.a.pause();$('#px').onclick=()=>{P.a.pause();$('#player').style.display='none'};
const listen=(fid,sid)=>tryit(async()=>{toast('Composing… first time can take a few seconds');const t=await api(`/farms/${fid}/track`+(sid?`?snapshot_id=${sid}`:''));play(t);return t});
/* ---------- websocket ---------- */
let ws;function connect(){if(!T)return;ws=new WebSocket((location.protocol=='https:'?'wss://':'ws://')+location.host+'/ws?token='+T);ws.onmessage=async e=>{const d=JSON.parse(e.data);if(d.type=='match'){toast('New match!');refresh()}else if(d.message.sender_farm!=S.me.farm.id){if(S.thread==d.message.match_id){const l=await api(`/matches/${S.thread}/messages`);paintThread(l)}else{toast('New message');refresh()}}else if(S.thread==d.message.match_id){paintThread(await api(`/matches/${S.thread}/messages`))}};ws.onclose=()=>setTimeout(connect,3000)}
async function refresh(){try{S.matches=await api('/matches');S.notif=S.matches.reduce((a,m)=>a+m.unread,0);S.notifN=(await api('/notifications')).filter(n=>!n.is_read).length;if(S.scr=='app'&&['disc','home','chat'].includes(S.tab)&&!S.ov&&!S.thread)draw()}catch(e){}}
/* ---------- shell ---------- */
function hdr(t,sub){return`<div class="row sb" style="margin-bottom:12px"><div><h1>${t}</h1><div class="mut">${sub||''}</div></div><div class="row"><button class="ic" onclick="ovNotif()" style="position:relative">${ic('bell')}${S.notifN?`<span class="dot" style="position:absolute;top:-2px;right:-2px">${S.notifN}</span>`:''}</button><button class="ic" onclick="ovSet()">${ic('gear')}</button></div></div>`}
function draw(){$('#app').dataset.screen=S.scr;Object.keys(maps).forEach(k=>{if(k!='ovmap'){maps[k].remove();delete maps[k]}});const m=$('#main');document.querySelectorAll('nav').forEach(e=>e.remove());const F={onb,auth,farmSetup,fieldEd,boot:()=>'<p class="mut">Loading…</p>'}[S.scr];const views={home,earth,disc,rot,co,fields:myFields,doctor:doctorPage,weather:weatherPage,match:matchPage,chat:chatPage,feed:feedPage,music:farmSymphonyPage,knowledge:knowledgePage,reports:reportsPage};m.innerHTML=F?F():(views[S.tab]||home)();if(S.scr=='app'){$('#app').insertAdjacentHTML('beforeend',shellNav());after();extraAfter()}else{after()}}
function tab(t){S.tab=t;draw()}
async function boot(){try{await load();S.scr=!S.me.farm?'farm':!S.me.fields.length?'field':'app';if(S.scr=='farm')S.scr='farmSetup';if(S.scr=='field')S.scr='fieldEd';connect()}catch(e){S.scr='auth'}draw()}
async function load(){S.me=await api('/me');if(S.me.farm){S.matches=await api('/matches');S.notif=S.matches.reduce((a,m)=>a+m.unread,0);S.notifN=(await api('/notifications')).filter(n=>!n.is_read).length;try{S.disc=await api('/discover');S.disc.concat(S.matches.map(m=>m.farm)).forEach(c=>S.known[c.id]=c)}catch(e){S.disc=[]}}}
/* ---------- onboarding / auth ---------- */
function onb(){const s=[['Know your land from space','NASA Earth observations plus your own field boundaries, soil and crop history build a Field DNA for every field.'],['Find farms like yours','Discover farmers with similar environmental conditions, match, and exchange real experience.'],['Plan, and hear your farm','Compare crop rotations, stress-test them with Climate Remix, get an AI action plan—and listen to your Farm Symphony.']][S.ob];return`<div style="display:flex;flex-direction:column;justify-content:space-between;min-height:92vh"><div class="row sb"><b style="color:var(--pri)">AgroMatch</b><button class="ic mut" onclick="S.scr='auth';draw()">Skip</button></div><div><h1 style="font-size:28px">${s[0]}</h1><p class="mut" style="font-size:15px">${s[1]}</p></div><div><div class="dots" style="text-align:center;margin:12px">${[0,1,2].map(i=>`<i class="${i==S.ob?'on':''}"></i>`).join('')}</div><button class="btn" onclick="S.ob<2?S.ob++:S.scr='auth';draw()">${S.ob<2?'Continue':'Get started'}</button></div></div>`}
function auth(){const r=S.auth=='register';return`<h1 style="margin-top:30px">${r?'Create account':'Welcome back'}</h1><p class="mut">${r?'Your data is stored in this app’s local database.':'Sign in to your farm.'}</p>${r?'<label>Name</label><input id="nm">':''}<label>Email</label><input id="em" type="email" autocomplete="email"><label>Password (6+ characters)</label><input id="pw" type="password"><button class="btn" onclick="doAuth()">${r?'Sign up':'Log in'}</button><p class="mut" style="text-align:center" onclick="S.auth='${r?'login':'register'}';draw()"><u>${r?'I already have an account':'Create a new account'}</u></p>`}
const doAuth=()=>tryit(async()=>{const r=await api('/'+(S.auth=='register'?'register':'login'),{b:{email:$('#em').value,password:$('#pw').value,name:$('#nm')?.value||''}});T=r.token;localStorage.tok=T;await boot()});
/* ---------- farm & field setup ---------- */
function farmSetup(){const f=S.me.farm||{};return`<h1 style="margin-top:14px">${f.id?'Edit farm':'Register your farm'}</h1><label>Farm name</label><input id="fn" value="${esc(f.name||'')}"><label>Find location</label><div class="row"><input id="fq" placeholder="Village, region or country" style="margin:4px 0 10px" value="${esc(f.region||'')}"><button class="btn s" onclick="findLoc()">Search</button></div><div id="fmap" class="map"></div><div class="mut" id="floc">${S.loc||f.id?`Location set: ${(S.loc||f).lat.toFixed(4)}, ${(S.loc||f).lon.toFixed(4)}`:'Search or tap the map to set farm location.'}</div><label style="display:block;margin-top:10px">Farming practice</label><select id="fp">${['conventional','no-till','organic','regenerative'].map(p=>`<option ${f.practice==p?'selected':''}>${p}</option>`).join('')}</select><label>Priorities</label><div>${['Save water','Soil health','Profit','Low inputs','Resilience','Knowledge sharing','Equipment sharing','Joint purchases'].map(p=>`<button class="chip ${S.pri.includes(p)?'on':''}" onclick="S.pri.includes('${p}')?S.pri.splice(S.pri.indexOf('${p}'),1):S.pri.push('${p}');this.classList.toggle('on')">${p}</button>`).join('')}</div><button class="btn" style="margin-top:12px" onclick="saveFarm()">${f.id?'Save':'Continue: add fields'}</button>${f.id?'<button class="btn o" style="margin-top:8px" onclick="S.scr=\'app\';draw()">Cancel</button>':''}`}
const findLoc=()=>tryit(async()=>{const g=await geocode($('#fq').value);setLoc(g.lat,g.lon,g.name)});
function setLoc(lat,lon,name){S.loc={lat,lon,name};$('#floc').textContent=`Location set: ${lat.toFixed(4)}, ${lon.toFixed(4)}`;const m=maps.fmap;m.flyTo({center:[lon,lat],zoom:11});if(S.mk)S.mk.remove();S.mk=new maplibregl.Marker({color:'#1F4D36'}).setLngLat([lon,lat]).addTo(m)}
const saveFarm=()=>tryit(async()=>{const l=S.loc||S.me.farm;if(!l||!$('#fn').value)throw new Error('Add a farm name and location');await api('/farm',{b:{name:$('#fn').value,region:S.loc?.name?.split(',').slice(0,2).join(',')||S.me.farm?.region||'',lat:l.lat,lon:l.lon,practice:$('#fp').value,priorities:S.pri}});await load();S.scr=S.me.fields.length?'app':'fieldEd';S.edit=null;S.pts=[];draw()});
const SOILS=['Unknown','Clay','Clay loam','Loam','Sandy loam','Sand','Silt loam'];
function fieldEd(){const f=S.edit?S.me.fields.find(x=>x.id==S.edit):null,y=new Date().getFullYear(),c=f?f.crops:[];return`<h1 style="margin-top:14px">${f?'Edit field':'Add a field'}</h1><p class="mut">Tap the map to place boundary corners. Satellite imagery is real; boundary is yours.</p><div class="row" style="gap:6px"><input id="sq" placeholder="Search place" style="margin:0"><button class="btn s" onclick="tryit(async()=>{const g=await geocode($('#sq').value);maps.fed.flyTo({center:[g.lon,g.lat],zoom:16})})">Go</button></div><div id="fed" class="map big" style="height:300px"></div><div class="row"><span class="mut" id="pc2">${S.pts.length} points</span><button class="btn o s" onclick="S.pts.pop();upd()">Undo</button><button class="btn o s" onclick="S.pts=[];upd()">Clear</button></div><label style="display:block;margin-top:10px">Field name</label><input id="ffn" value="${esc(f?.name||'')}"><div class="g2"><div><label>Soil type</label><select id="fs">${SOILS.map(s=>`<option ${f?.soil==s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Soil data source</label><select id="fss">${[['unknown','Not known'],['farmer-provided','My estimate'],['farmer-tested','Lab soil test']].map(s=>`<option value="${s[0]}" ${f?.soil_source==s[0]?'selected':''}>${s[1]}</option>`).join('')}</select></div></div><label>Crop history (oldest → latest)</label><div class="row">${[2,1,0].map((k,i)=>`<select id="cr${i}" style="flex:1">${CROPS.map(x=>`<option ${(c[i]||'').split(' ').pop()==x?'selected':''}>${x}</option>`).join('')}</select>`).join('')}</div><div class="mut" style="margin-bottom:10px">Years: ${y-2}, ${y-1}, ${y}</div><button class="btn" id="svf" onclick="saveField()">Save field & fetch NASA data</button>${S.me.fields.length?'<button class="btn o" style="margin-top:8px" onclick="S.scr=\'app\';S.edit=null;draw()">Cancel</button>':''}`}
function upd(){const m=maps.fed;if(m&&m.getSource('draw')){m.getSource('draw').setData(geo(S.pts))}$('#pc2').textContent=S.pts.length+' points'}
function geo(p){const f=[];if(p.length>=3)f.push({type:'Feature',geometry:{type:'Polygon',coordinates:[[...p,p[0]]]}});if(p.length>=2)f.push({type:'Feature',geometry:{type:'LineString',coordinates:p}});p.forEach(q=>f.push({type:'Feature',geometry:{type:'Point',coordinates:q}}));return fc(f)}
const saveField=()=>tryit(async()=>{if(S.pts.length<3)throw new Error('Draw at least 3 corners');const y=new Date().getFullYear(),b={name:$('#ffn').value||'Field',polygon:S.pts,soil:$('#fs').value=='Unknown'?'':$('#fs').value,soil_source:$('#fss').value,crops:[2,1,0].map((k,i)=>`${y-k} ${$('#cr'+i).value}`)};$('#svf').disabled=true;$('#svf').textContent='Fetching NASA POWER data (up to ~30 s)…';try{S.edit?await api('/fields/'+S.edit,{m:'PUT',b}):await api('/fields',{b})}finally{}await load();S.scr='app';S.tab='home';S.edit=null;S.pts=[];draw();toast('Field saved. Field DNA ready')});
/* ---------- home ---------- */
function alerts(f){const m=f.snapshots[0].metrics,out=[];if(m.wetness<.3)out.push(['Low root-zone soil wetness ('+m.wetness+')','warn']);if(m.trend<-.04)out.push(['Soil wetness declining vs 12 months ago','warn']);if(m.rain_cv>1.3)out.push(['Erratic monthly rainfall (CV '+m.rain_cv+')','warn']);return out.map(a=>`<div class="warn">${f.name}: ${a[0]} · ${m.simulated?tag('s'):tag('n')}</div>`).join('')}
function home(){const fs=S.me.fields,farm=S.me.farm,first=fs[0];return hdr('Hello, '+esc(S.me.user.name||'farmer'),esc(farm.name)+' · '+esc(farm.region))+
`<div class="hero-panel"><div class="hero-eyebrow">INTELLIGENCE FROM ABOVE</div><h2>Better decisions begin with understanding the land.</h2><p>Connect climate intelligence, field observations and grower experience. From orbit to action.</p><button class="btn s" onclick="tab('earth')">Explore Earth →</button></div>`+
`<div class="section-eyebrow">FARM AT A GLANCE</div><div class="g2"><div class="metric"><span class="mut">Fields monitored</span><b>${fs.length}</b></div><div class="metric"><span class="mut">Total area</span><b>${fs.reduce((a,f)=>a+f.area_ha,0).toFixed(1)} ha</b></div></div><div class="row sb" style="margin-top:20px"><h2>My fields</h2><button class="chip" onclick="tab('fields')">View all</button></div><div class="feature-grid">${fs.map(f=>{const s=f.snapshots[0],m=s?.metrics;return `<div class="field-tile" onclick="ovField(${f.id})"><div class="row sb"><h3>${esc(f.name)}</h3>${s?lvpill(s.level,s.harmony):''}</div><div class="mut">${f.area_ha} ha · ${esc(f.soil||'soil unknown')} · ${m?.simulated?tag('s'):tag('n')}</div><div class="key-stats"><span>Rain / year<b>${m?.rain_mm??'—'} mm</b></span><span>Mean temperature<b>${m?.temp_c??'—'} °C</b></span></div><span class="read-more">Explore field →</span></div>`}).join('')}</div><button class="btn o" onclick="S.scr='fieldEd';S.edit=null;S.pts=[];draw()">+ Add field</button><div class="row sb" style="margin-top:20px"><h2>Early signals</h2><button class="chip" onclick="tab('doctor')">Field Doctor</button></div>${fs.map(alerts).join('')||'<p class="mut">No thresholds triggered. Routine inspection remains important.</p>'}<div class="feature-grid"><div class="feature-panel"><div class="section-eyebrow">WEATHER OUTLOOK</div><h2>Next 7 days</h2><div id="homeForecast"><p class="mut">Loading forecast…</p></div><button class="btn o s" onclick="tab('weather')">Full climate view</button></div><div class="feature-panel"><div class="section-eyebrow">FARM COMMUNITY</div><h2>Grower updates</h2><div id="homeFeed"><p class="mut">Loading community…</p></div><button class="btn o s" onclick="tab('feed')">Open Farm Feed</button></div></div><div class="mut">NASA POWER provides coarse regional climate context, not measurements at each field. Last available data: ${first?.snapshots[0]?.metrics.last_obs||'unknown'}.</div>`}
/* ---------- earth ---------- */
function earth(){const d=new Date(Date.now()-10*864e5).toISOString().slice(0,10);
 return hdr('Earth','Нажми на выделенное поле → получи погоду и региональные NASA-данные для выбранной точки')+
 `<div class="earth-search"><input id="eq" placeholder="Город или координаты: 43.24, 76.92" aria-label="Поиск места"><button class="btn s" onclick="tryit(async()=>{const g=await geocode($('#eq').value);maps.earth.flyTo({center:[g.lon,g.lat],zoom:13,pitch:45})})">Найти</button><button class="btn o s" onclick="zoomToMyFields()">Мои поля</button></div>
 <div class="earth-controls"><div class="section-eyebrow">СЛОЙ КАРТЫ</div><div id="lays" class="earth-layer-tabs">${Object.entries(LAY).map(([k,v])=>`<button class="chip ${k==S.layer?'on':''}" data-k="${k}" onclick="setLayer('${k}',$('#ed').value)">${esc(v.n)}</button>`).join('')}</div>
 <div class="earth-options"><label>Дата снимка <input type="date" id="ed" value="${d}" max="${new Date().toISOString().slice(0,10)}" onchange="setLayer(S.layer,this.value)"></label><button class="btn o s" onclick="const m=maps.earth;m.easeTo({pitch:m.getPitch()>10?0:60})">2D / 3D</button></div></div>
 <div class="earth-map-wrap"><div id="earth" class="map big"></div><div class="earth-map-hint">📍 Нажмите внутри зелёного контура своего поля, чтобы увидеть условия именно в выбранной точке.</div></div>
 <div id="esel" class="point-panel"><div class="feature-panel"><b>Выбери точку на поле</b><p class="mut">Показываются данные погодной модели и климатической сетки. Это не измерения датчика на участке.</p></div></div>
 <div id="einfo" class="card"></div>${satellitePanel()}`;
}
function zoomToMyFields(){
 const fields=S.me?.fields||[],m=maps.earth;
 if(!m||!fields.length){toast('Добавьте поле, чтобы перейти к нему');return;}
 const pts=fields.flatMap(f=>f.polygon||[]);
 if(pts.length)fit(m,pts);
}
function pointMetric(name,value,unit='',note=''){
 return `<div class="earth-point-metric"><span>${esc(name)}</span><strong>${value===null||value===undefined?'—':esc(value)}${esc(unit)}</strong><small>${esc(note)}</small></div>`;
}
async function loadMapPoint(fid,lat,lon,refresh=false){
 const el=$('#esel');if(!el)return;
 const f=S.me.fields.find(x=>x.id===fid);if(!f)return;
 if(S.earthMarker){S.earthMarker.remove();S.earthMarker=null}
 if(maps.earth&&window.maplibregl)S.earthMarker=new maplibregl.Marker({color:'#F0A438'}).setLngLat([lon,lat]).addTo(maps.earth);
 const seq=S.earthPointSeq=(S.earthPointSeq||0)+1;
 el.innerHTML=`<div class="feature-panel"><h2>${esc(f.name)}</h2><p class="mut">Получаем реальные данные для выбранной точки (${lat.toFixed(5)}, ${lon.toFixed(5)})…</p></div>`;
 try{
  const r=await api(`/fields/${fid}/point-conditions`,{b:{lat,lon,refresh}});
  if(seq!==S.earthPointSeq||!$('#esel'))return;
  S.pointReport=r;
  const w=r.forecast, d=w?.days?.[0]||{}, power=r.power, ind=power?.indicators||{};
  let weatherHtml='<p class="warn">Прогноз недоступен: '+esc(r.unavailable?.forecast||'нет данных')+'</p>';
  if(w){
   weatherHtml='<div class="earth-point-metrics">'+
    pointMetric('🌡️ Макс. температура',d.high==null?null:Number(d.high).toFixed(1),' °C','Прогноз на сегодня')+
    pointMetric('❄️ Мин. температура',d.low==null?null:Number(d.low).toFixed(1),' °C','Прогноз на сегодня')+
    pointMetric('🌧️ Осадки',d.rain==null?null:Number(d.rain).toFixed(1),' мм','Прогноз за сутки')+
    pointMetric('☔ Вероятность дождя',d.rain_chance==null?null:Math.round(d.rain_chance),' %','Максимум за сутки')+
    pointMetric('💨 Ветер',w.wind_today,' км/ч','Максимум за сегодня')+
    pointMetric('💧 Влажность воздуха',w.humidity_today,' %','Средняя первых 24 часов')+
    '</div><p class="mut">Источник: '+esc(w.source)+' · '+esc(d.date||'')+' · модель, не датчик на поле.</p>';
  }
  let nasaHtml='<p class="warn">NASA POWER недоступен: '+esc(r.unavailable?.power||'нет данных')+'</p>';
  if(power){
   const period=power.period||{};
   nasaHtml='<div class="earth-point-metrics">'+
    pointMetric('🌧️ Осадки',ind.rain_total_mm,' мм','Сумма за доступные дни')+
    pointMetric('🌡️ Средняя температура',ind.mean_temp_c,' °C','Региональная оценка')+
    pointMetric('☀️ Солнечная энергия',ind.mean_solar_kwh_m2_day,' кВт·ч/м²/сут','Среднее за период')+
    pointMetric('❄️ Морозные дни',ind.frost_days_min_le_0c,' дн.','Tmin ≤ 0 °C')+
    pointMetric('🔥 Жаркие дни',ind.heat_days_max_ge_35c,' дн.','Tmax ≥ 35 °C')+
    pointMetric('📅 Дней с данными',period.valid_days,'','С '+esc(period.first_observation||'—')+' по '+esc(period.last_observation||'—'))+
    '</div><p class="mut">Источник: '+esc(power.source)+'. Региональная климатическая сетка (не измерение точно в поле).</p>';
  }
  el.innerHTML=`<div class="feature-panel earth-point-card">
  <div class="row sb"><div><div class="section-eyebrow">ВЫБРАННАЯ ТОЧКА</div><h2>${esc(f.name)}</h2><p class="mut">Широта: ${lat.toFixed(5)} · Долгота: ${lon.toFixed(5)} · ${Number(f.area_ha).toLocaleString('ru-RU')} га</p></div><span class="tag f_">API</span></div>
  <h3>🌦️ Прогноз сегодня · Open-Meteo</h3>${weatherHtml}
  <h3>🛰️ NASA POWER · доступные данные за 30 дней</h3>${nasaHtml}
  <div class="earth-point-actions"><button class="btn s" onclick="S.extraField=${fid};tab('weather')">Прогноз на 7 дней</button><button class="btn o s" onclick="ovField(${fid})">Информация о поле</button><button class="btn o s" onclick="loadMapPoint(${fid},${lat},${lon},true)">↻ Обновить</button></div>
  <button class="btn o s" onclick="downloadPointReport()">⬇ Скачать данные точки (JSON)</button><div class="earth-provenance"><b>Происхождение и точность</b><p>🟦 <b>Open-Meteo:</b> метеорологическая модель по координатам; это прогноз, а не показание датчика.</p><p>🟩 <b>NASA POWER:</b> исторические значения в региональной ячейке сетки, могут быть одинаковыми для соседних участков.</p><p>🛰️ <b>NASA GIBS:</b> визуальные спутниковые изображения без числовых измерений по клику.</p></div><p class="footnote">Отсутствующие данные показаны знаком «—»; численные значения нельзя считать полевыми измерениями.</p></div>`;
 }catch(e){if(seq===S.earthPointSeq&&$('#esel'))$('#esel').innerHTML='<div class="warn">Ошибка данных: '+esc(e.message)+'</div>'}
}
function downloadPointReport(){
 if(!S.pointReport){toast('Сначала выберите точку на карте');return;}
 const report=S.pointReport;
 const filename='agromatch-field-'+report.field_id+'-point.json';
 const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'});
 const url=URL.createObjectURL(blob);
 const link=document.createElement('a');
 link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();
 setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function after(){if(S.scr=='fieldEd'){const m=mkMap('fed',{center:S.me.farm?[S.me.farm.lon,S.me.farm.lat]:[0,20],zoom:S.me.farm?15:2,onload:m=>{m.addSource('draw',{type:'geojson',data:geo(S.pts)});m.addLayer({id:'dfill',type:'fill',source:'draw',filter:['==','$type','Polygon'],paint:{'fill-color':'#7CFC9A','fill-opacity':.3}});m.addLayer({id:'dline',type:'line',source:'draw',filter:['==','$type','LineString'],paint:{'line-color':'#fff','line-width':2.5}});m.addLayer({id:'dpt',type:'circle',source:'draw',filter:['==','$type','Point'],paint:{'circle-radius':5,'circle-color':'#1F4D36','circle-stroke-color':'#fff','circle-stroke-width':2}});if(S.edit){const f=S.me.fields.find(x=>x.id==S.edit);if(!S.pts.length)S.pts=f.polygon.slice();upd();fit(m,S.pts)}}});m.on('click',e=>{S.pts.push([e.lngLat.lng,e.lngLat.lat]);upd()});m.getCanvas().style.cursor='crosshair'}
 if(S.scr=='farmSetup'){const f=S.me?.farm,m=mkMap('fmap',{center:f?[f.lon,f.lat]:[0,20],zoom:f?11:1.4});m.on('click',e=>setLoc(e.lngLat.lat,e.lngLat.lng,''));if(f){S.mk=new maplibregl.Marker({color:'#1F4D36'}).setLngLat([f.lon,f.lat]).addTo(m)}}
 if(S.scr=='app'&&S.tab=='earth'){const fs=S.me.fields,c=S.cam;mkMap('earth',{center:c?c.center:fs[0]?[fs[0].lon,fs[0].lat]:[0,20],zoom:c?c.zoom:fs[0]?14:1.5,pitch:c?c.pitch:fs[0]?50:0,onload:m=>{addFields(m,fs,(id,point)=>{const f=fs.find(x=>x.id==id);if(!f)return;loadMapPoint(f.id,point.lat,point.lng)});setLayer(S.layer,$('#ed').value)}});maps.earth.on('moveend',()=>{const m=maps.earth;if(m)S.cam={center:m.getCenter().toArray(),zoom:m.getZoom(),pitch:m.getPitch()}});maps.earth.on('error',e=>{if(e.sourceId=='gibs')$('#einfo')&&0})}
 if(S.scr=='app'&&S.tab=='rot')loadRot();if(S.scr=='app'&&['disc','match'].includes(S.tab))bindSwipe();if(S.scr=='app'&&S.tab=='co')0}
/* ---------- overlays ---------- */
function ovOpen(h){closeOv();$('#app').insertAdjacentHTML('beforeend',`<div class="over" id="ov"><div class="row" style="margin-bottom:8px"><button class="ic" onclick="closeOv()">${ic('back')}</button></div>${h}</div>`);S.ov=1}
function closeOv(){if(maps.ovmap){maps.ovmap.remove();delete maps.ovmap}$('#ov')?.remove();S.ov=null;S.thread=null}
function ovField(id){const f=S.me.fields.find(x=>x.id==id),s=f.snapshots[0],m=s.metrics,mo=m.monthly.slice(-12),lab=mo.map(x=>x.m.slice(5)),snap=l=>f.snapshots.find(x=>x.label==l);
 ovOpen(`<div class="row sb"><h1>${esc(f.name)}</h1>${lvpill(s.level,s.harmony)}</div><div class="mut">${f.area_ha} ha · ${f.lat.toFixed(4)}, ${f.lon.toFixed(4)}</div><div id="ovmap" class="map"></div><div class="card"><div class="row sb"><b>Field DNA</b>${m.simulated?tag('s'):tag('n')}</div><div class="row"><div>${dna(m)}</div><div class="mut" style="font-size:12px">Fingerprint: <span style="color:var(--pri)">■</span> soil wetness <span style="color:#4a8fb5">■</span> rain <span style="color:#c79a2b">■</span> temperature, 12 months. Unique to this field’s location and conditions.</div></div><div class="g2"><div class="metric"><span class="mut">Rain (12 mo)</span><b>${m.rain_mm} mm</b></div><div class="metric"><span class="mut">Mean temp</span><b>${m.temp_c} °C</b></div><div class="metric"><span class="mut">Soil wetness*</span><b>${m.wetness}</b></div><div class="metric"><span class="mut">Vegetation (NDVI)</span><b style="font-size:13px">not loaded</b></div></div><div class="mut" style="margin-top:8px">${esc(m.source)}<br>Last observation: ${m.last_obs||'n/a'} · *root-zone wetness fraction 0–1 (modelled). ${esc(m.limits)}</div></div>
 <div class="card"><b>Rainfall (mm / month)</b>${bars(mo.map(x=>x.rain),lab)}<b>Temperature (°C)</b>${line(mo.map(x=>x.temp),lab,'#c79a2b')}<b>Soil wetness</b>${line(mo.map(x=>x.wet),lab)}</div>
 <div class="card"><b>Harmony score breakdown</b>${(s.comps||[]).map(c=>`<div class="row sb mut"><span>${c.name} (${Math.round(c.weight*100)}%)</span><span>${Math.round(c.value*100)}</span></div><div class="bar"><i style="width:${c.value*100}%"></i></div>`).join('')}</div>
 <div class="card"><b>Compare over time</b><table style="width:100%;font-size:13px;margin-top:6px"><tr class="mut"><td></td><td>Harmony</td><td>Rain</td><td>Temp</td><td>Wet</td></tr>${f.snapshots.map(x=>`<tr><td>${x.label}</td><td>${lvpill(x.level,x.harmony)}</td><td>${x.metrics.rain_mm}</td><td>${x.metrics.temp_c}</td><td>${x.metrics.wetness}</td></tr>`).join('')}</table></div>
 <div class="card"><b>Soil & crops</b><div class="mut">Soil: ${esc(f.soil||'unknown')} ${f.soil_source=='farmer-tested'?tag('f'):f.soil_source=='farmer-provided'?tag('f'):'(no verified soil data)'}</div><div class="rot" style="margin-top:6px">${f.crops.map(c=>`<span>${esc(c)}</span>`).join('')}</div><button class="btn o s" style="margin-top:8px" onclick="closeOv();S.scr='fieldEd';S.edit=${f.id};S.pts=[];draw()">Edit boundary & info</button></div>
 <div class="card"><b>Farm Symphony</b><div class="mut">Original procedural composition from this field’s environment. Before & After:</div><div style="margin-top:8px">${f.snapshots.map(x=>`<button class="chip" onclick="listen(${S.me.farm.id},${x.id}).then(t=>t&&ovTrack(t))">▶ ${x.label} · ${x.level}</button>`).join('')}</div></div>`);
 mkMap('ovmap',{center:[f.lon,f.lat],zoom:15,onload:mm=>{addFields(mm,[f]);fit(mm,f.polygon)}});maps.ovmap=maps.ovmap}
function ovTrack(t){ovOpen(`${art(t)}<h1 style="margin-top:10px">${esc(t.title)}</h1><div>${lvpill(t.level,t.harmony)} <span class="mut">Environmental Harmony ${Math.round(t.harmony)}/100</span></div><div class="row" style="margin:10px 0"><button class="btn s" onclick="play(S.cur)">▶ Play</button><button class="btn o s" onclick="tryit(async()=>{const r=await api('/tracks/${t.id}/save',{b:{}});toast(r.saved?'Saved to collection':'Removed')})">♥ Save</button></div><div class="card"><b>How the environment shaped it</b>${t.info.mapping.map(l=>`<p class="mut" style="margin:6px 0">• ${esc(l)}</p>`).join('')}<div class="warn">${esc(t.info.mode)}.${t.info.simulated_data?' Built from SIMULATED data.':''}</div></div>`);S.cur=t}
const miniFarm=c=>`<div class="card" onclick="ovFarm(${c.id})"><div class="row sb"><b>${esc(c.name)}</b>${lvpill(c.level,c.harmony)}</div><div class="mut">${esc(c.region)}</div></div>`;
function ovFarm(id){tryit(async()=>{const c=await api('/farms/'+id),mt=S.matches.find(m=>m.farm.id==id),s=c.similarity;ovOpen(`<h1>${esc(c.name)}</h1><div class="mut">${esc(c.region)} · ${esc(c.practice)} ${c.demo?tag('s'):''}</div><div class="card"><div class="row sb"><b>Farm compatibility</b><b style="font-size:24px;color:var(--pri)">${s?s.score+'%':'–'}</b></div>${s?s.parts.map(p=>`<div class="row sb mut"><span>${p.name}</span><span>${p.detail}</span></div><div class="bar"><i style="width:${p.closeness}%"></i></div>`).join('')+`<div class="warn">${s.note}</div>`:''}</div><div class="card"><b>Climate</b> ${c.metrics.simulated?tag('s'):tag('n')}<div class="mut">Rain ${c.metrics.rain_mm} mm · ${c.metrics.temp_c} °C · soil wetness ${c.metrics.wetness} · trend ${c.metrics.trend}</div><div class="mut" style="margin-top:6px">Rotation history</div><div class="rot">${c.rotation.map(x=>`<span>${x}</span>`).join('')}</div></div><div class="row"><button class="btn" onclick="closeOv();listen(${c.id}).then(t=>t&&ovTrack(t))">▶ Listen to farm symphony</button></div>${mt?`<button class="btn o" style="margin-top:8px" onclick="ovThread(${mt.match_id})">Message</button>`:''}`)})}
function ovNotif(){tryit(async()=>{const n=await api('/notifications');ovOpen(`<div class="row sb"><h1>Notifications</h1><span class="mut">${n.filter(z=>!z.is_read).length} unread</span></div>${n.length?n.map(z=>`<div class="notif-entry ${z.is_read?'is-read':''}" onclick="gotoNotification(${z.id},'${esc(z.target)}')"><b>${esc(z.category.toUpperCase())}</b><p>${esc(z.text)}</p><span class="mut">${when(z.created)}</span></div>`).join(''):'<p class="mut">No notifications yet.</p>'}`)})}
async function gotoNotification(id,target){await tryit(async()=>{await api('/notifications/'+id+'/read',{b:{}});S.notifN=Math.max(0,(S.notifN||0)-1);closeOv();if(target.startsWith('match:')){await refresh();ovThread(+target.split(':')[1])}else if(target.startsWith('post:'))tab('feed');else if(target.startsWith('field:')){S.extraField=+target.split(':')[1];tab('earth')}else tab('home')})}

function ovSet(){tryit(async()=>{const st=await api('/status'),u=S.me.user;ovOpen(`<h1>Profile & settings</h1><div class="card"><b>${esc(u.name)}</b><div class="mut">${esc(u.email)}<br>${esc(S.me.farm.name)} · ${esc(S.me.farm.region)}</div><button class="btn o s" style="margin-top:8px" onclick="closeOv();S.scr='farmSetup';draw()">Edit farm</button></div><div class="card"><b>Services</b><div class="mut">AI providers: ${st.ai_providers.length?st.ai_providers.map(p=>p.tag+' ('+p.kind+')').join(' → '):'none configured (Copilot disabled)'}<br>Music: ${st.music}<br>NASA POWER: ${st.nasa_power}</div></div><button class="btn o" onclick="document.documentElement.dataset.theme=document.documentElement.dataset.theme=='dark'?'light':'dark'">Toggle dark mode</button><button class="btn o" style="margin-top:8px" onclick="T='';localStorage.tok='';location.reload()">Log out</button>`)})}
/* ---------- discover ---------- */
function disc(){const seg=[['swipe','Swipe'],['matches','Matches'],['msgs','Messages'],['music','Music']];return hdr('Discover','Farms with similar conditions')+`<div class="seg">${seg.map(s=>`<button class="${S.seg==s[0]?'on':''}" onclick="S.seg='${s[0]}';draw()">${s[1]}${s[0]=='msgs'&&S.notif?` <span class="dot">${S.notif}</span>`:''}</button>`).join('')}</div>`+({swipe:swipeV,matches:matchV,msgs:msgV,music:musicV})[S.seg]()}
function swipeV(){const c=S.disc[0];if(!c)return`<div class="card" style="text-align:center;padding:30px"><h3>You’re all caught up</h3><p class="mut">More farms appear as more farmers register.</p></div>`;const s=c.similarity,m=c.metrics;return`<div class="swipe"><div class="sc" id="top"><div class="row sb"><div><h2 style="margin:0">${esc(c.name)}</h2><div class="mut">${esc(c.region)} · ${esc(c.practice)} ${c.demo?tag('s'):''}</div></div><div style="text-align:center"><b style="font-size:26px;color:var(--pri)">${s?s.score:'–'}%</b><div class="mut" style="font-size:11px">farm<br>compatibility</div></div></div><div class="g2" style="margin:10px 0"><div class="metric"><span class="mut">Rain</span><b>${m.rain_mm} mm</b></div><div class="metric"><span class="mut">Temp</span><b>${m.temp_c} °C</b></div><div class="metric"><span class="mut">Soil wetness</span><b>${m.wetness}</b></div><div class="metric"><span class="mut">Symphony</span><b style="font-size:14px">${lvpill(c.level,c.harmony)}</b></div></div>${c.metrics.monthly?.length?line(c.metrics.monthly.slice(-12).map(x=>x.wet),c.metrics.monthly.slice(-12).map(x=>x.m.slice(5))):''}<div class="mut">Rotation history</div><div class="rot">${c.rotation.map(x=>`<span>${x}</span>`).join('')}</div><div class="row" style="margin-top:10px"><button class="btn o s" onclick="listen(${c.id})">▶ Listen</button><button class="btn o s" onclick="ovFarm(${c.id})">Full profile</button><button class="btn o s" onclick="S.expl=!S.expl;draw()">How scored?</button></div>${S.expl&&s?`<div class="mut" style="margin-top:8px">${s.parts.map(p=>`${p.name}: ${p.detail} (${p.closeness}% close)`).join('<br>')}<br><i>${s.note}</i></div>`:''}<div class="warn">Similar climate ≠ same soil, crops or practices. Environmental data from ${m.simulated?'SIMULATED demo profile':'NASA POWER'}.</div></div></div><div class="act"><button onclick="doSwipe(false)">${ic('x')}</button><button class="y" onclick="doSwipe(true)">${ic('heart')}</button></div>`}
function bindSwipe(){const t=$('#top');if(!t)return;let x0=0,dx=0,d=false;t.onpointerdown=e=>{if(e.target.closest('button'))return;d=true;x0=e.clientX;t.setPointerCapture(e.pointerId)};t.onpointermove=e=>{if(!d)return;dx=e.clientX-x0;t.style.transform=`translateX(${dx}px) rotate(${dx/25}deg)`};t.onpointerup=()=>{d=false;if(dx>100)doSwipe(true);else if(dx<-100)doSwipe(false);else{t.style.transform='';dx=0}}}
const doSwipe=like=>tryit(async()=>{const c=S.disc[0];S.expl=false;const r=await api('/swipe',{b:{to_farm:c.id,like}});S.disc.shift();S.known[c.id]=c;if(r.match){S.matches=await api('/matches');draw();ovOpen(`<div style="text-align:center;padding-top:50px"><h1 style="color:var(--pri)">It’s a match</h1><p class="mut">You and ${esc(c.name)} liked each other.${r.simulated?' (Demo farm: simulated auto-match.)':''}</p><button class="btn" onclick="ovThread(${r.match_id})">Send a message</button><button class="btn o" style="margin-top:8px" onclick="closeOv()">Keep browsing</button></div>`)}else draw()});
const matchV=()=>S.matches.length?S.matches.map(m=>`<div class="card"><div class="row sb"><b onclick="ovFarm(${m.farm.id})">${esc(m.farm.name)}</b><span class="tag n">MATCH</span></div><div class="mut">${esc(m.farm.region)} · ${m.farm.similarity?.score??'–'}% similar</div><div class="row" style="margin-top:8px"><button class="btn s" onclick="ovThread(${m.match_id})">Message</button><button class="btn o s" onclick="listen(${m.farm.id}).then(t=>t&&ovTrack(t))">▶ Symphony</button></div></div>`).join(''):'<p class="mut">No matches yet. A match needs both farmers to like each other.</p>';
const msgV=()=>S.matches.length?S.matches.map(m=>`<div class="card" onclick="ovThread(${m.match_id})"><div class="row sb"><b>${esc(m.farm.name)}</b>${m.unread?`<span class="dot">${m.unread}</span>`:''}</div><div class="mut">${m.last?esc(m.last.kind=='text'?m.last.body:'Shared '+m.last.kind)+' · '+when(m.last.created):'No messages yet'}</div></div>`).join(''):'<p class="mut">Match with a farm to start chatting.</p>';
function musicV(){const known=Object.values(S.known);tryit(async()=>{S.tracks=await api('/tracks');const el=$('#tl');if(el)el.innerHTML=S.tracks.map(t=>`<div class="card"><div class="row sb"><b onclick='ovTrack(${JSON.stringify(t).replace(/'/g,'&#39;')})'>${esc(t.title)}</b>${lvpill(t.level,Math.round(t.harmony))}</div><div class="mut">${esc(t.farm_name||'')} · ${t.kind}</div><div class="row" style="margin-top:6px"><button class="btn s" onclick='play(${JSON.stringify(t).replace(/'/g,'&#39;')})'>▶</button><button class="btn o s" onclick="tryit(async()=>{await api('/tracks/${t.id}/save',{b:{}});toast('Updated collection')})">${t.saved?'♥ Saved':'♡ Save'}</button>${t.farm_id?`<button class="btn o s" onclick="ovFarm(${t.farm_id})">Visit farm</button>`:''}</div></div>`).join('')||'<p class="mut">No compositions yet.</p>'});return`<div class="card"><b>World farm orchestra</b><div class="mut">Pick 2+ farms to blend their environments into one regional composition.</div>${known.map(c=>`<label class="chk"><input type="checkbox" class="orc" value="${c.id}"><span style="color:var(--ink);font-weight:400">${esc(c.name)} <span class="mut">${esc(c.region)}</span></span></label>`).join('')}<button class="btn s" onclick="orchestra()">Generate orchestra</button></div><div class="card"><b>Listen to farms</b><div style="margin-top:6px">${known.map(c=>`<button class="chip" onclick="listen(${c.id}).then(t=>t&&ovTrack(t))">▶ ${esc(c.name)}</button>`).join('')}</div></div><h2>Library</h2><div id="tl"><p class="mut">Loading…</p></div>`}
const orchestra=()=>tryit(async()=>{const ids=[...document.querySelectorAll('.orc:checked')].map(e=>+e.value);if(ids.length<2)throw new Error('Select at least 2 farms');toast('Composing orchestra… this takes a few seconds');const t=await api('/orchestra',{b:{farm_ids:ids}});play(t);ovTrack(t)});
/* ---------- chat ---------- */
function paintThread(l){const el=$('#msgs');if(!el)return;const me=S.me.farm.id;el.innerHTML=l.map(m=>{const mine=m.sender_farm==me,p=m.payload;let b=esc(m.body);if(m.kind=='farm')b=`🌾 Shared farm: <u onclick="ovFarm(${p.farm_id})">${esc(p.name)}</u>`;if(m.kind=='rotation')b=`🔄 Rotation “${esc(p.name)}”<div class="rot">${(p?.seq||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;if(m.kind=='track')b=`🎵 <u onclick='play(${JSON.stringify(p).replace(/'/g,'&#39;')})'>${esc(p.title)} (▶)</u>`;return`<div class="bub ${mine?'u':''}">${b}<small>${when(m.created)}</small></div>`}).join('');el.scrollTop=el.scrollHeight;$('#ov').scrollTop=1e6}
function ovThread(mid){const m=S.matches.find(x=>x.match_id==mid);ovOpen(`<h2 style="margin-top:0" onclick="ovFarm(${m.farm.id})">${esc(m.farm.name)} <span class="mut" style="font-size:12px">· ${esc(m.farm.region)}</span></h2><div id="msgs"></div><div style="position:sticky;bottom:0;background:var(--bg);padding-top:8px"><div class="rot" style="margin-bottom:6px"><button class="chip" onclick="share(${mid},'farm')">Share my farm</button><button class="chip" onclick="share(${mid},'rotation')">Share rotation</button><button class="chip" onclick="share(${mid},'track')">Share symphony</button></div><div class="row"><input id="mi" placeholder="Message…" style="margin:0" onkeydown="if(event.key=='Enter')sendMsg(${mid})"><button class="btn s" onclick="sendMsg(${mid})">Send</button></div></div>`);S.thread=mid;tryit(async()=>{paintThread(await api(`/matches/${mid}/messages`));refresh()})}
const sendMsg=mid=>tryit(async()=>{const v=$('#mi').value.trim();if(!v)return;$('#mi').value='';await api(`/matches/${mid}/messages`,{b:{body:v}})});
const share=(mid,k)=>tryit(async()=>{let b={kind:k,body:'',payload:null};if(k=='farm')b.payload={farm_id:S.me.farm.id,name:S.me.farm.name};if(k=='rotation'){const f=S.me.fields[0],r=await api(`/rotation?field_id=${f.id}`),s=r.strategies.find(x=>x.key=='ai');b.payload={name:s.name,seq:s.seq}}if(k=='track'){b.payload=await api(`/farms/${S.me.farm.id}/track`)}await api(`/matches/${mid}/messages`,{b});});
/* ---------- rotation ---------- */
function rot(){const fs=S.me.fields;S.rotF=S.rotF||fs[0].id;return hdr('Rotation','Four rotation scenarios · Farmer priorities · Climate Remix')+`<label>Field</label><select onchange="S.rotF=+this.value;loadRot()">${fs.map(f=>`<option value="${f.id}" ${f.id==S.rotF?'selected':''}>${esc(f.name)}</option>`).join('')}</select><label>Peer farm (matched)</label><select onchange="S.rotP=this.value;loadRot()"><option value="">None</option>${S.matches.map(m=>`<option value="${m.farm.id}" ${m.farm.id==S.rotP?'selected':''}>${esc(m.farm.name)}</option>`).join('')}</select><div id="rotb"><p class="mut">Loading…</p></div>`}
let rt;const loadRot=()=>{clearTimeout(rt);rt=setTimeout(()=>tryit(async()=>{const s=S.sc;S.rot=await api(`/rotation?field_id=${S.rotF}&rain=${s.rain}&temp=${s.temp}&drought=${s.drought}`+(S.rotP?`&peer_farm_id=${S.rotP}`:''));paintRot()}),150)};
function paintRot(){const r=S.rot,el=$('#rotb');if(!el)return;const st=r.strategies,c=st.find(x=>x.key==S.rs&&!x.empty)||st[0],sc=S.sc;
 el.innerHTML=`<div class="seg">${st.map(x=>`<button class="${x.key==c.key?'on':''}" onclick="S.rs='${x.key}';paintRot()">${x.name.split(' ')[0]}</button>`).join('')}</div>${S.rs!=c.key?'<div class="warn">'+esc(st.find(x=>x.key==S.rs).why)+'</div>':''}<div class="card"><div class="row sb"><h3>${c.name}</h3>${c.key=='ai'?tag('a'):c.key=='current'?tag('f'):'<span class="tag f_">PEER-REPORTED</span>'}</div><div class="rot" style="margin:8px 0">${c.seq.map((x,i)=>`<span>Y${i+1} ${x}</span>`).join('')}</div><div class="mut">${esc(c.why)}</div><div class="g2" style="margin-top:10px"><div class="metric"><span class="mut">Water need</span><b>${c.water_mm} mm</b></div><div class="metric"><span class="mut">Effective rain</span><b>${c.supply_mm} mm</b></div><div class="metric"><span class="mut">Soil cover</span><b>${c.cover}</b></div><div class="metric"><span class="mut">N-fixation</span><b>${c.n_fix} kg/ha</b></div></div><div class="row sb" style="margin-top:10px"><span>Water-stress risk index</span><b>${Math.round(c.stress*100)} · ${c.yield_risk}</b></div><div class="bar"><i style="width:${c.stress*100}%;background:${c.stress<.15?'#2f7a4a':c.stress<.35?'#c79a2b':'#a8322a'}"></i></div>${c.pros.map(p=>`<p class="mut" style="color:var(--pri)">+ ${esc(p)}</p>`).join('')}${c.cons.map(p=>`<p class="mut" style="color:var(--bad)">− ${esc(p)}</p>`).join('')}${(c.priority_notes||[]).length?`<div class="feature-panel" style="margin-top:10px"><b>How this relates to your farm priorities</b>${c.priority_notes.map(p=>`<p class="mut">${esc(p)}</p>`).join('')}</div>`:''}<details><summary class="mut">Assumptions & missing information</summary>${c.assumptions.map(a=>`<p class="mut">• ${esc(a)}</p>`).join('')}${c.missing.map(a=>`<p class="mut">? ${esc(a)}</p>`).join('')}</details></div>
 <div class="card"><b>Water-stress comparison</b>${st.filter(x=>!x.empty).map(x=>`<div class="row" style="margin-top:6px"><span class="mut" style="width:62px;font-size:12px">${x.name.split(' ')[0]}</span><div class="bar" style="flex:1"><i style="width:${x.stress*100}%;background:${x.stress<.15?'#2f7a4a':x.stress<.35?'#c79a2b':'#a8322a'}"></i></div><b style="font-size:12px;width:28px">${Math.round(x.stress*100)}</b></div>`).join('')}</div>
 <div class="card"><div class="row sb"><b>Climate Remix</b>${tag('s')}</div><div class="warn">${r.scenario.note} Baseline: ${r.baseline.rain_mm} mm, ${r.baseline.temp_c} °C (${r.baseline.simulated?'SIMULATED':'NASA POWER'}).</div><label>Rainfall change: ${sc.rain}%</label><input type="range" min="-40" max="30" value="${sc.rain}" style="padding:0" oninput="S.sc.rain=+this.value;this.previousElementSibling.textContent='Rainfall change: '+this.value+'%';loadRot()"><label>Warming: +${sc.temp} °C</label><input type="range" min="0" max="4" step=".5" value="${sc.temp}" style="padding:0" oninput="S.sc.temp=+this.value;this.previousElementSibling.textContent='Warming: +'+this.value+' °C';loadRot()"><label>Drought intensity: ${Math.round(sc.drought*100)}%</label><input type="range" min="0" max="1" step=".1" value="${sc.drought}" style="padding:0" oninput="S.sc.drought=+this.value;this.previousElementSibling.textContent='Drought intensity: '+Math.round(this.value*100)+'%';loadRot()"></div><button class="btn" onclick="S.cop.mode='do';tab('co')">Get action plan</button>`}
/* ---------- copilot ---------- */
const MODES=[['ask','Ask AI'],['do','What to do'],['plant','What to plant'],['buy','What to buy'],['budget','Budget'],['calendar','Calendar']];
function co(){const c=S.cop,fs=S.me.fields;c.field=c.field||fs[0].id;return hdr('Copilot','AI assistant · advisory only')+`<div class="seg">${MODES.map(m=>`<button class="${c.mode==m[0]?'on':''}" onclick="S.cop.mode='${m[0]}';draw()">${m[1]}</button>`).join('')}</div><label>Field context</label><select onchange="S.cop.field=+this.value">${fs.map(f=>`<option value="${f.id}" ${f.id==c.field?'selected':''}>${esc(f.name)}</option>`).join('')}</select><div id="cout">${c.mode=='ask'?c.hist.map(m=>`<div class="bub ${m.role=='user'?'u':''} md">${md(m.content)}</div>`).join(''):c.out[c.mode]?`<div class="card md">${md(c.out[c.mode].text)}<div class="mut">${tag('a')} via ${esc(c.out[c.mode].provider)}</div></div>`:''}</div>${c.busy?'<p class="mut">Thinking…</p>':''}<div class="row"><input id="cin" placeholder="${c.mode=='ask'?'Ask about your farm…':c.mode=='buy'||c.mode=='budget'?'Optional: local prices, budget limit…':'Optional: extra details…'}" style="margin:0" onkeydown="if(event.key=='Enter')ask()"><button class="btn s" onclick="ask()">${c.mode=='ask'?'Send':'Generate'}</button></div><div class="warn">AI suggestions use your Field DNA (NASA POWER, coarse) and what you entered. They may be wrong—verify with a local agronomist. No prices or soil results are invented.</div>`}
const ask=()=>tryit(async()=>{const c=S.cop,v=$('#cin').value.trim();if(c.mode=='ask'&&!v)return;c.busy=true;if(c.mode=='ask')c.hist.push({role:'user',content:v});draw();try{const r=await api('/copilot',{b:{mode:c.mode,message:v,field_id:c.field,history:c.mode=='ask'?c.hist.slice(0,-1):[]}});if(c.mode=='ask')c.hist.push({role:'assistant',content:r.text+`\n(via ${r.provider})`});else c.out[c.mode]=r}catch(e){if(c.mode=='ask')c.hist.push({role:'assistant',content:'⚠ '+e.message});else c.out[c.mode]={text:'⚠ '+e.message,provider:'none'}}c.busy=false;draw()});
T?boot():draw();
